cat > $W/repro-$v.ts <<EOF
import { Hono } from '$SRC/hono'
import { validator } from '$SRC/validator'
import { HonoRequest } from '$SRC/request'

const run = async (label: string, fn: () => Promise<unknown>) => {
  try { console.log(label, '=>', JSON.stringify(await fn())) } catch (e) { console.log(label, '=> THROW', (e as Error).message) }
}

const mkMultipart = () => { const fd = new FormData(); fd.append('foo', 'bar'); return new Request('http://localhost/post', { method: 'POST', body: fd }) }
const mkUrl = () => new Request('http://localhost/post', { method: 'POST', body: 'foo=bar', headers: { 'content-type': 'application/x-www-form-urlencoded' } })

// 1. validator('form') then parseBody in handler
for (const [name, mk] of [['multipart', mkMultipart], ['urlencoded', mkUrl]] as const) {
  const app = new Hono()
  app.post('/post', validator('form', (v) => v), async (c) => c.json(await c.req.parseBody()))
  await run('validator(form) -> parseBody [' + name + ']', async () => { const r = await app.request(mk()); return [r.status, await r.text()] })
}
// 2. c.req.formData() then parseBody
for (const [name, mk] of [['multipart', mkMultipart], ['urlencoded', mkUrl]] as const) {
  await run('formData() -> parseBody [' + name + ']', async () => { const req = new HonoRequest(mk()); await req.formData(); return await req.parseBody() })
}
// 3. parseBody then formData() (the stated goal of the change)
await run('parseBody -> formData() [multipart]', async () => { const req = new HonoRequest(mkMultipart()); await req.parseBody(); return [...(await req.formData()).entries()] })
// 4. text() then parseBody (pre-existing path)
await run('text() -> parseBody [multipart]', async () => { const req = new HonoRequest(mkMultipart()); await req.text(); return await req.parseBody() })
// 5. bodyCache keys after parseBody
await run('bodyCache keys after parseBody', async () => { const req = new HonoRequest(mkMultipart()); await req.parseBody(); return Object.keys(req.bodyCache) })
// 6. plain Request mixed case via raw platform formData()
await run('platform Request.formData() mixed-case', async () => { const src = mkMultipart(); const ct = src.headers.get('content-type')!.replace('multipart/form-data','Multipart/Form-Data'); const r = new Request('http://x/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'content-type': ct } }); return [...(await r.formData()).entries()] })
EOF
$C/node_modules/.bin/esbuild $W/repro-$v.ts --bundle --platform=node --format=esm --outfile=$W/repro-$v.mjs --log-level=error && echo "===== $v =====" && node $W/repro-$v.mjs
done

